package rediskey

import (
	"errors"
	"fmt"
	"strconv"
	"strings"

	"farmgame/internal/actorrouting"
	"farmgame/internal/workidentity"
)

const redisKeyRoot = "classic-farm"

var (
	ErrInvalidNamespace = errors.New("rediskey: invalid namespace")
	ErrInvalidBucketRef = errors.New("rediskey: invalid bucket reference")
	ErrInvalidComponent = errors.New("rediskey: invalid key component")
	ErrCrossSlot        = errors.New("rediskey: keys do not share one hash tag")
)

// RedisKey is a complete Redis key generated by a versioned builder.
// Business code must not construct authority keys by string concatenation.
type RedisKey string

func (k RedisKey) String() string { return string(k) }

// Namespace isolates environments and zones that share a physical Redis.
// Components are deliberately strict so user-controlled braces or separators
// can never alter the Redis Cluster hash tag.
type Namespace struct {
	Environment string
	Zone        string
}

func NewNamespace(environment, zone string) (Namespace, error) {
	n := Namespace{Environment: environment, Zone: zone}
	if err := n.Validate(); err != nil {
		return Namespace{}, err
	}
	return n, nil
}

func (n Namespace) Validate() error {
	if !validLowerSegment(n.Environment, 32) || !validLowerSegment(n.Zone, 32) {
		return ErrInvalidNamespace
	}
	return nil
}

func (n Namespace) prefix() string {
	return redisKeyRoot + ":" + n.Environment + ":" + n.Zone
}

// KeyPrefix is the text every key of this namespace opens with, ahead of any
// hash tag. It exists for readers that have to address the namespace as a whole
// — counting or clearing what it holds — and is not a way to assemble a single
// key by hand: those still come from the builders below.
func (n Namespace) KeyPrefix() string { return n.prefix() }

// AuthorityBucketRef is the versioned persistence placement. VirtualShard is
// numerically equal to the auth-v1 bucket id, but remains a distinct concept.
type AuthorityBucketRef struct {
	domain        actorrouting.RouteDomain
	layoutVersion string
	virtualShard  uint32
}

func newAuthorityBucketRef(domain actorrouting.RouteDomain, layoutVersion string, virtualShard uint32) (AuthorityBucketRef, error) {
	ref := AuthorityBucketRef{domain: domain, layoutVersion: layoutVersion, virtualShard: virtualShard}
	if err := ref.Validate(); err != nil {
		return AuthorityBucketRef{}, err
	}
	return ref, nil
}

func (r AuthorityBucketRef) Validate() error {
	if _, err := authorityDomainSegment(r.domain); err != nil || !validLayoutVersion(r.layoutVersion) {
		return ErrInvalidBucketRef
	}
	return nil
}

func (r AuthorityBucketRef) Domain() actorrouting.RouteDomain { return r.domain }
func (r AuthorityBucketRef) LayoutVersion() string            { return r.layoutVersion }
func (r AuthorityBucketRef) VirtualShard() uint32             { return r.virtualShard }

// WorkflowBucketRef is independent of worker count and Pod assignment.
type WorkflowBucketRef struct {
	layoutVersion string
	bucketID      uint32
	workflowID    string
}

func newWorkflowBucketRef(layoutVersion string, bucketID uint32, workflowID string) (WorkflowBucketRef, error) {
	ref := WorkflowBucketRef{layoutVersion: layoutVersion, bucketID: bucketID, workflowID: workflowID}
	if err := ref.Validate(); err != nil {
		return WorkflowBucketRef{}, err
	}
	return ref, nil
}

func (r WorkflowBucketRef) Validate() error {
	if !validLayoutVersion(r.layoutVersion) {
		return ErrInvalidBucketRef
	}
	return nil
}

func (r WorkflowBucketRef) LayoutVersion() string { return r.layoutVersion }
func (r WorkflowBucketRef) BucketID() uint32      { return r.bucketID }
func (r WorkflowBucketRef) WorkflowID() string    { return r.workflowID }

// AuthorityKeyBuilder is the only supported constructor for auth-v1 keys.
// All keys passed to one Lua operation must be checked with AssertSameSlot.
type AuthorityKeyBuilder interface {
	ShardAuthority(AuthorityBucketRef) (RedisKey, error)
	ActorRecord(AuthorityBucketRef, uint64) (RedisKey, error)
	SourceOrder(AuthorityBucketRef, string, string) (RedisKey, error)
	SourceSchedule(AuthorityBucketRef, string, string) (RedisKey, error)
	SourceDueIndex(AuthorityBucketRef) (RedisKey, error)
	SourceScheduleDueIndex(AuthorityBucketRef) (RedisKey, error)
	ReceiptDueIndex(AuthorityBucketRef) (RedisKey, error)
	BucketMeta(AuthorityBucketRef) (RedisKey, error)
	BucketScanLease(AuthorityBucketRef) (RedisKey, error)
	AssertSameSlot(...RedisKey) error
}

type AuthorityKeys struct {
	profile  PhysicalProfile
	resolver AuthorityShardResolver
}

func NewAuthorityKeys(profile PhysicalProfile, resolver AuthorityShardResolver) (AuthorityKeys, error) {
	if err := profile.Validate(); err != nil {
		return AuthorityKeys{}, err
	}
	if err := validateAuthorityResolverProfile(resolver); err != nil {
		return AuthorityKeys{}, err
	}
	return AuthorityKeys{profile: profile, resolver: resolver}, nil
}

func (b AuthorityKeys) HashTag(ref AuthorityBucketRef) (string, error) {
	if err := ref.Validate(); err != nil {
		return "", err
	}
	if ref.layoutVersion != b.profile.AuthorityLayoutVersion {
		return "", ErrInvalidBucketRef
	}
	domain, _ := authorityDomainSegment(ref.domain)
	return b.profile.Namespace.prefix() + ":auth:" + domain + ":" + ref.layoutVersion + ":s:" + strconv.FormatUint(uint64(ref.virtualShard), 10), nil
}

func (b AuthorityKeys) key(ref AuthorityBucketRef, suffix string) (RedisKey, error) {
	tag, err := b.HashTag(ref)
	if err != nil {
		return "", err
	}
	return RedisKey("{" + tag + "}:" + suffix), nil
}

func (b AuthorityKeys) ShardAuthority(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "shard-authority")
}

func (b AuthorityKeys) ActorRecord(ref AuthorityBucketRef, actorID uint64) (RedisKey, error) {
	if actorID == 0 {
		return "", ErrInvalidComponent
	}
	shard, err := b.resolver.ShardFor(ref.domain, actorID)
	if err != nil || shard != ref.virtualShard {
		return "", ErrInvalidBucketRef
	}
	return b.key(ref, "actor:"+strconv.FormatUint(actorID, 10))
}

// ActorRecordFor builds the read-only Actor record key from the same immutable
// routing calculator used by writes. Query code must not reimplement the
// virtual-shard hash or construct Redis hash tags manually.
func (b AuthorityKeys) ActorRecordFor(address actorrouting.ActorAddress) (RedisKey, error) {
	ref, err := b.profile.AuthorityBucketForActor(b.resolver, address)
	if err != nil {
		return "", err
	}
	return b.ActorRecord(ref, address.ActorID)
}

func (b AuthorityKeys) SourceOrder(ref AuthorityBucketRef, workType, workID string) (RedisKey, error) {
	if !validStableName(workType) || workidentity.ValidateStableOpaqueID(workID) != nil {
		return "", ErrInvalidComponent
	}
	return b.key(ref, "order:"+workType+":"+workID)
}

// SourceSchedule is the mutable schedule record kept physically separate from
// immutable SourceOrder records while retaining the exact authority bucket
// hash tag. Its DueIndex member uses sr1_ identity and cannot collide with a
// wr1_ order member having the same type/id.
func (b AuthorityKeys) SourceSchedule(ref AuthorityBucketRef, scheduleType, scheduleID string) (RedisKey, error) {
	if !validStableName(scheduleType) || workidentity.ValidateStableOpaqueID(scheduleID) != nil {
		return "", ErrInvalidComponent
	}
	return b.key(ref, "schedule:"+scheduleType+":"+scheduleID)
}

func (b AuthorityKeys) SourceDueIndex(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "due")
}

// SourceScheduleDueIndex is the dedicated mutable-schedule DueIndex added by
// plan 82 C5. It shares the exact authority bucket hash tag with every other
// key in one Lua operation, so discovery of sr1_ members never scans wr1_
// order members in the legacy shared DueIndex.
func (b AuthorityKeys) SourceScheduleDueIndex(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "schedule-due")
}

func (b AuthorityKeys) ReceiptDueIndex(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "receipt-due")
}

func (b AuthorityKeys) BucketMeta(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "bucket-meta")
}

func (b AuthorityKeys) BucketScanLease(ref AuthorityBucketRef) (RedisKey, error) {
	return b.key(ref, "scan-lease")
}

func (b AuthorityKeys) AssertSameSlot(keys ...RedisKey) error { return AssertSameSlot(keys...) }

// WorkflowKeys builds keys for independent recoverable workflows.
type WorkflowKeys struct{ profile PhysicalProfile }

func NewWorkflowKeys(profile PhysicalProfile) (WorkflowKeys, error) {
	if err := profile.Validate(); err != nil {
		return WorkflowKeys{}, err
	}
	return WorkflowKeys{profile: profile}, nil
}

func (b WorkflowKeys) HashTag(ref WorkflowBucketRef) (string, error) {
	if err := ref.Validate(); err != nil {
		return "", err
	}
	if ref.layoutVersion != b.profile.WorkflowLayoutVersion || ref.bucketID >= b.profile.WorkflowBucketCount {
		return "", ErrInvalidBucketRef
	}
	return b.profile.Namespace.prefix() + ":wf:" + ref.layoutVersion + ":b:" + strconv.FormatUint(uint64(ref.bucketID), 10), nil
}

func (b WorkflowKeys) key(ref WorkflowBucketRef, suffix string) (RedisKey, error) {
	tag, err := b.HashTag(ref)
	if err != nil {
		return "", err
	}
	return RedisKey("{" + tag + "}:" + suffix), nil
}

func (b WorkflowKeys) Work(ref WorkflowBucketRef) (RedisKey, error) {
	if workidentity.ValidateStableOpaqueID(ref.workflowID) != nil {
		return "", ErrInvalidComponent
	}
	expected, err := b.profile.WorkflowBucket(ref.workflowID)
	if err != nil || expected.bucketID != ref.bucketID || expected.layoutVersion != ref.layoutVersion {
		return "", ErrInvalidBucketRef
	}
	return b.key(ref, "work:"+ref.workflowID)
}

func (b WorkflowKeys) DueIndex(ref WorkflowBucketRef) (RedisKey, error) {
	return b.key(ref, "due")
}

func (b WorkflowKeys) BucketMeta(ref WorkflowBucketRef) (RedisKey, error) {
	return b.key(ref, "bucket-meta")
}

func (b WorkflowKeys) BucketScanLease(ref WorkflowBucketRef) (RedisKey, error) {
	return b.key(ref, "scan-lease")
}

func (b WorkflowKeys) AssertSameSlot(keys ...RedisKey) error { return AssertSameSlot(keys...) }

type RuntimeKeys struct{ namespace Namespace }

func NewRuntimeKeys(namespace Namespace) (RuntimeKeys, error) {
	if err := namespace.Validate(); err != nil {
		return RuntimeKeys{}, err
	}
	return RuntimeKeys{namespace: namespace}, nil
}

func (b RuntimeKeys) Session(playerID uint64) (RedisKey, error) {
	if playerID == 0 {
		return "", ErrInvalidComponent
	}
	return RedisKey(fmt.Sprintf("{%s:rt:session:v1:p:%d}:authority", b.namespace.prefix(), playerID)), nil
}

// ConnectionTicket shares the SessionAuthority tag required by contract 26's
// one-shot ticket redemption and active-session replacement Lua boundary.
func (b RuntimeKeys) ConnectionTicket(playerID uint64, ticketHash string) (RedisKey, error) {
	if playerID == 0 || !validLowerHex(ticketHash, 64) {
		return "", ErrInvalidComponent
	}
	return RedisKey(fmt.Sprintf("{%s:rt:session:v1:p:%d}:ticket:%s", b.namespace.prefix(), playerID, ticketHash)), nil
}

func (b RuntimeKeys) FriendNavigation(playerID, sessionEpoch uint64) (RedisKey, error) {
	if playerID == 0 || sessionEpoch == 0 {
		return "", ErrInvalidComponent
	}
	return RedisKey(fmt.Sprintf("%s:rt:friend-nav:v1:%d:%d", b.namespace.prefix(), playerID, sessionEpoch)), nil
}

type ProjectionKeys struct{ namespace Namespace }

func NewProjectionKeys(namespace Namespace) (ProjectionKeys, error) {
	if err := namespace.Validate(); err != nil {
		return ProjectionKeys{}, err
	}
	return ProjectionKeys{namespace: namespace}, nil
}

// resultDirectoryLayoutVersion is the frozen ResultDirectory layout (31
// §2.4/§8.3): proj:result:v2:<player_id>. v1 never became a published
// production format, so there is no v1 read fallback and no dual write.
const resultDirectoryLayoutVersion = "v2"

// ResultDirectory is explicitly versioned apart from the generic byID
// projections: only this kind is v2, the others stay at their current
// layout.
func (b ProjectionKeys) ResultDirectory(playerID uint64) (RedisKey, error) {
	if playerID == 0 {
		return "", ErrInvalidComponent
	}
	return RedisKey(fmt.Sprintf("%s:proj:result:%s:%d", b.namespace.prefix(), resultDirectoryLayoutVersion, playerID)), nil
}

func (b ProjectionKeys) FarmOpportunity(farmID uint64) (RedisKey, error) {
	return b.byID("farm-opportunity", farmID)
}

func (b ProjectionKeys) Redpoint(playerID uint64) (RedisKey, error) {
	return b.byID("redpoint", playerID)
}

func (b ProjectionKeys) PublicProfile(playerID uint64) (RedisKey, error) {
	return b.byID("public-profile", playerID)
}

func (b ProjectionKeys) byID(kind string, id uint64) (RedisKey, error) {
	if id == 0 {
		return "", ErrInvalidComponent
	}
	return RedisKey(fmt.Sprintf("%s:proj:%s:v1:%d", b.namespace.prefix(), kind, id)), nil
}

func authorityDomainSegment(domain actorrouting.RouteDomain) (string, error) {
	switch domain {
	case actorrouting.DomainPlayer:
		return "player", nil
	case actorrouting.DomainFarm:
		return "farm", nil
	case actorrouting.DomainFarmWorker:
		return "farm-worker", nil
	default:
		return "", ErrInvalidBucketRef
	}
}

func validLowerSegment(value string, max int) bool {
	if len(value) == 0 || len(value) > max {
		return false
	}
	for i := 0; i < len(value); i++ {
		c := value[i]
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '-' && c != '_' {
			return false
		}
	}
	return value[0] >= 'a' && value[0] <= 'z'
}

func validLayoutVersion(value string) bool {
	if len(value) < 2 || value[0] != 'v' {
		return false
	}
	for _, c := range value[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func validStableName(value string) bool {
	if len(value) == 0 || len(value) > 64 || strings.ContainsAny(value, "{}:") {
		return false
	}
	for i := 0; i < len(value); i++ {
		c := value[i]
		if (c < 'A' || c > 'Z') && (c < '0' || c > '9') && c != '_' {
			return false
		}
	}
	return true
}

func validLowerHex(value string, length int) bool {
	if len(value) != length {
		return false
	}
	for i := 0; i < len(value); i++ {
		if (value[i] < '0' || value[i] > '9') && (value[i] < 'a' || value[i] > 'f') {
			return false
		}
	}
	return true
}
